  'sabine.compliance_active': { fr: 'RISQUE PROCÈS RÉDUIT', en: 'LAWSUIT RISK REDUCED', es: 'RIESGO DEMANDA REDUCIDO', de: 'KLAGERISIKO GESENKT', it: 'RISCHIO CAUSE RIDOTTO', ru: 'РИСК ИСКОВ СНИЖЕН', zh: '诉讼风险已降' },
