  'juridique.modal_title': { fr: 'JURIDIQUE · Sabine', en: 'LEGAL · Sabine', es: 'JURÍDICO · Sabine', de: 'RECHT · Sabine', it: 'LEGALE · Sabine', ru: 'ПРАВО · Сабина', zh: '法务 · 萨宾' },
  'juridique.intro_none': { fr: "Pas de juriste embauchée. Si une plainte tombe, c'est à toi de trancher : défendre, régler ou ignorer. Embaucher une juriste sécurise tout ça.", en: "No lawyer hired. If a complaint lands, it's up to you to call: defend, settle, or ignore. Hiring a lawyer secures all this.", es: "Sin abogada contratada. Si llega una demanda, tú decides: defender, transar o ignorar. Contratar a una jurista asegura todo esto.", de: "Keine Juristin angestellt. Bei einer Klage entscheidest du: verteidigen, einigen oder ignorieren. Eine Juristin einzustellen sichert das ab.", it: "Nessuna giurista assunta. Se arriva una denuncia, sta a te: difendere, transare o ignorare. Assumere una giurista mette al sicuro tutto.", ru: "Юрист не нанят. Если придёт жалоба, решать тебе: защищаться, мириться или игнорировать. Найм юриста всё это закрывает.", zh: "未聘律师。如有投诉，由你决定：抗辩、和解或忽视。聘请一名律师可全面保障。" },
  'juridique.intro_jr': { fr: "Sabine Juriste Junior : 1 procès gérés/an, dommages divisés par 1.4. Au-delà du quota, à toi de décider.", en: "Sabine Junior Lawyer: 1 lawsuit handled/year, damages divided by 1.4. Past the quota, your call.", es: "Sabine Jurista Junior: 1 juicio gestionado/año, daños divididos por 1.4. Pasado el cupo, tú decides.", de: "Sabine Junior-Juristin: 1 Klage/Jahr behandelt, Schäden geteilt durch 1.4. Über dem Kontingent entscheidest du.", it: "Sabine Giurista Junior: 1 causa gestita/anno, danni divisi per 1.4. Oltre la quota, decidi tu.", ru: "Сабина Младший юрист: 1 иск в год, ущерб делится на 1.4. Сверх лимита решаешь ты.", zh: "萨宾初级法务：每年处理1起诉讼，损失除以1.4。超额由你决定。" },
  'juridique.intro_sr': { fr: "Sabine Avocate Senior : 3 procès/an gérés à 40% des dommages. Au-delà, redevient manuel.", en: "Sabine Senior Lawyer: 3 lawsuits/year handled at 40% damages. Past quota, back to manual.", es: "Sabine Abogada Senior: 3 juicios/año al 40% de daños. Después, manual.", de: "Sabine Senior-Anwältin: 3 Klagen/Jahr bei 40% Schäden. Danach manuell.", it: "Sabine Avvocata Senior: 3 cause/anno al 40% dei danni. Oltre, manuale.", ru: "Сабина Старший юрист: 3 иска/год при 40% ущерба. Сверх, вручную.", zh: "萨宾高级律师：每年3起诉讼，损失40%。超额转人工。" },
  'juridique.intro_dg': { fr: "Sabine DG Juridique : immunité quasi totale, dommages à 10% sur tous les procès. À ce niveau, plus rien ne te touche vraiment.", en: "Sabine Chief Legal Officer: near-total immunity, damages at 10% on all lawsuits. At this level, nothing really touches you.", es: "Sabine DG Jurídico: inmunidad casi total, daños al 10% en todos. A este nivel, casi nada te toca.", de: "Sabine Chefjuristin: nahezu vollständige Immunität, 10% Schäden bei allen Klagen. Auf diesem Niveau berührt dich kaum etwas.", it: "Sabine DG Legale: immunità quasi totale, danni al 10% su tutte. A questo livello, quasi nulla ti tocca.", ru: "Сабина Главный юрисконсульт: почти полный иммунитет, 10% ущерба по всем. На этом уровне почти ничто тебя не задевает.", zh: "萨宾法务总监：近乎完全免疫，所有诉讼损失10%。此级别下几乎无人能动你。" },
