  'warehouse.robert_title': { fr: 'ROBERT, AGENT IMMOBILIER', en: 'ROBERT, REAL ESTATE AGENT', es: 'ROBERT, AGENTE INMOBILIARIO', de: "ROBERT, IMMOBILIENMAKLER" , it: "ROBERT, AGENTE IMMOBILIARE", ru: "РОБЕР, АГЕНТ ПО НЕДВИЖИМОСТИ", zh: "罗贝尔, 房地产经纪人"},
  'warehouse.robert_intro': { fr: "Robert vous présente l'entrepôt. Il a bossé pour les pros du froid pendant 20 ans, il sait ce qu'il vous faut.", en: 'Robert walks you through the warehouse. He worked with cold-chain pros for 20 years, he knows what you need.', es: 'Robert te enseña la nave. Trabajó con profesionales del frío durante 20 años, sabe lo que necesitas.', de: "Robert führt dich durch das Lager. Er hat 20 Jahre mit Kühlketten-Profis gearbeitet, er weiß, was du brauchst." , it: "Robert ti mostra il magazzino. Ha lavorato 20 anni con professionisti della catena del freddo, sa di cosa hai bisogno.", ru: "Робер проводит вас по складу. Он 20 лет работал с профессионалами холодовой цепи, он знает, что вам нужно.", zh: "罗贝尔带你参观仓库。他与冷链专业人士共事20年，知道你需要什么。"},
  'warehouse.robert_quote': { fr: "Vous signez ici, et dans deux semaines vous embauchez votre premier chauffeur. Garanti, j'en ai vu passer des dizaines comme vous.", en: 'You sign here, and in two weeks you hire your first driver. Guaranteed, I\'ve seen dozens like you.', es: 'Firmas aquí, y en dos semanas contratas a tu primer chófer. Garantizado, he visto a docenas como tú.', de: "Du unterschreibst hier, und in zwei Wochen stellst du deinen ersten Fahrer ein. Garantiert, ich habe Dutzende wie dich gesehen." , it: "", ru: "", zh: ""},
