  'mission.intro': { fr: "Pour passer à l'étape suivante, la marque doit franchir 5 paliers stratégiques. Tu peux y aller dans n'importe quel ordre.", en: "To reach the next stage, the brand must clear 5 strategic milestones. You can tackle them in any order.", es: "Para alcanzar la siguiente etapa, la marca debe superar 5 hitos estratégicos. Puedes abordarlos en cualquier orden.", de: "Um die nächste Stufe zu erreichen, muss die Marke 5 strategische Meilensteine schaffen. Reihenfolge frei wählbar." , it: "Per raggiungere la fase successiva, il marchio deve superare 5 traguardi strategici. Puoi affrontarli in qualsiasi ordine.", ru: "Чтобы перейти на следующий этап, бренд должен преодолеть 5 стратегических рубежей. Можно решать их в любом порядке.", zh: "要进入下一阶段，品牌必须达成5个战略里程碑。你可以按任意顺序攻克。"},
  'mission.visibility': { fr: 'VISIBILITÉ', en: 'VISIBILITY', es: 'VISIBILIDAD', de: "SICHTBARKEIT" , it: "VISIBILITÀ", ru: "ВИДИМОСТЬ", zh: "曝光度"},
  'mission.visibility_short': { fr: 'Visibilité', en: 'Visibility', es: 'Visibilidad', de: "Sichtbarkeit" , it: "Visibilità", ru: "Видимость", zh: "曝光度"},
