  'mission.competition': { fr: 'CONCURRENCE', en: 'COMPETITION', es: 'COMPETENCIA', de: "WETTBEWERB" , it: "CONCORRENZA", ru: "КОНКУРЕНЦИЯ", zh: "竞争"},
  'mission.competition_short': { fr: 'Concurrence', en: 'Competition', es: 'Competencia', de: "Wettbewerb" , it: "Concorrenza", ru: "Конкуренция", zh: "竞争"},
  'mission.competition_desc': { fr: 'Dépasser TOUS les concurrents en parts de marché, devenir le n°1.', en: 'Beat ALL competitors in market share, become the n°1.', es: 'Superar a TODOS los competidores en cuota de mercado, ser el n°1.', de: "Schlage ALLE Konkurrenten im Marktanteil, werde die Nr. 1." , it: "Batti TUTTI i concorrenti per quota di mercato, diventa il n°1.", ru: "Обойти ВСЕХ конкурентов по доле рынка, стать №1.", zh: "在市场份额上击败所有竞争对手,,成为第一。"},
  'mission.perennity': { fr: 'PÉRENNITÉ', en: 'PERENNITY', es: 'PERENNIDAD', de: "BESTÄNDIGKEIT" , it: "SOLIDITÀ", ru: "УСТОЙЧИВОСТЬ", zh: "可持续"},
