  'gameover.title': { fr: 'FAILLITE, FIN DE PARTIE', en: 'BANKRUPTCY, GAME OVER', es: 'QUIEBRA, FIN DE PARTIDA', de: "INSOLVENZ, SPIEL VORBEI" , it: "BANCAROTTA, GAME OVER", ru: "БАНКРОТСТВО, КОНЕЦ ИГРЫ", zh: "破产, 游戏结束"},
  'gameover.line1': { fr: 'Salaires impayés.', en: 'Salaries unpaid.', es: 'Salarios impagados.', de: "Gehälter unbezahlt." , it: "Stipendi non pagati.", ru: "Зарплаты не выплачены.", zh: "工资未付。"},
  'gameover.double_miss': { fr: "Vous n'avez pas pu assurer deux fois sur une année le paiement de vos salaires et charges. L'entreprise est mise en liquidation.", en: "You failed twice within a year to cover your wages and charges. The company is being liquidated.", es: "No pudo asegurar dos veces en un año el pago de salarios y cargos. La empresa entra en liquidación.", de: "Du hast zweimal binnen eines Jahres Löhne und Kosten nicht decken können. Das Unternehmen wird liquidiert." , it: "Hai fallito due volte in un anno nel coprire stipendi e spese. L'azienda viene liquidata.", ru: "Вы дважды за год не смогли покрыть зарплаты и расходы. Компания ликвидируется.", zh: "你在一年内两次无法支付工资和费用。公司正在清算。"},
  'gameover.year_debt': { fr: "L'année s'est terminée sans que les salaires dus soient réglés. Vos employés claquent la porte. L'entreprise ferme.", en: "The year ended with wages still unpaid. Your employees walk out for good. The company shuts down.", es: "El año terminó sin saldar los salarios pendientes. Sus empleados se van definitivamente. La empresa cierra.", de: "Das Jahr endete mit weiterhin unbezahlten Löhnen. Deine Mitarbeiter gehen endgültig. Das Unternehmen schließt." , it: "L'anno è finito con gli stipendi ancora non pagati. I tuoi dipendenti se ne vanno per sempre. L'azienda chiude.", ru: "Год закончился с невыплаченными зарплатами. Ваши сотрудники уходят навсегда. Компания закрывается.", zh: "这一年结束时工资仍未支付。你的员工永久离职。公司关闭。"},
  'gameover.line2': { fr: 'Factures impayées.', en: 'Bills unpaid.', es: 'Facturas impagadas.', de: "Rechnungen unbezahlt." , it: "Bollette non pagate.", ru: "Счета не оплачены.", zh: "账单未付。"},
  'gameover.line3': { fr: 'Trésorerie dans le rouge.', en: 'Cash flow in the red.', es: 'Tesorería en rojo.', de: "Cashflow im roten Bereich." , it: "Liquidità in rosso.", ru: "Денежный поток в минусе.", zh: "现金流为负。"},
  'gameover.line4': { fr: "La société n'est plus en mesure d'honorer ses engagements. Procédure de cessation d'activité enclenchée.", en: 'The company can no longer honor its commitments. Liquidation proceedings initiated.', es: 'La empresa ya no puede cumplir sus compromisos. Procedimiento de cese de actividad iniciado.', de: "Das Unternehmen kann seine Verpflichtungen nicht mehr erfüllen. Liquidationsverfahren eingeleitet." , it: "L'azienda non può più onorare i suoi impegni. Procedura di liquidazione avviata.", ru: "Компания больше не может выполнять обязательства. Начата процедура ликвидации.", zh: "公司无法再履行承诺。已启动清算程序。"},
  'gameover.stats_title': { fr: 'BILAN FINAL', en: 'FINAL BALANCE', es: 'BALANCE FINAL', de: "SCHLUSSBILANZ" , it: "BILANCIO FINALE", ru: "ИТОГОВЫЙ БАЛАНС", zh: "最终结算"},
