  'gameover.stat_debt': { fr: "Salaires dus", en: 'Wages owed', es: 'Salarios pendientes', de: "Geschuldete Löhne" , it: "Stipendi dovuti", ru: "Долг по зарплате", zh: "欠付工资"},
  'gameover.stat_bill': { fr: 'Factures dues', en: 'Bills owed', es: 'Facturas pendientes', de: "Geschuldete Rechnungen" , it: "Bollette dovute", ru: "Долг по счетам", zh: "欠付账单"},
