  'staff.help_title':     { fr: 'COMMENT ÇA MARCHE', en: 'HOW IT WORKS', es: 'CÓMO FUNCIONA', de: "SO FUNKTIONIERT ES" , it: "COME FUNZIONA", ru: "КАК ЭТО РАБОТАЕТ", zh: "运作方式"},
  'staff.help_moral':     { fr: 'Indicateur de bien-être (0-100). Descend de −1 tous les 30s. Si trop bas, ton employé peut faire grève et bloquer son poste.', en: 'Wellbeing meter (0-100). Drops by −1 every 30s. If too low, the employee may strike and freeze their station.', es: 'Indicador de bienestar (0-100). Baja −1 cada 30s. Si está muy bajo, el empleado puede ir a la huelga y bloquear su puesto.', de: "Wohlbefinden (0-100). Sinkt alle 30s um −1. Zu niedrig: Mitarbeiter streikt und blockiert seinen Posten." , it: "Indicatore di benessere (0-100). Cala di −1 ogni 30s. Se troppo basso, il dipendente può scioperare e bloccare la sua postazione.", ru: "Индикатор благополучия (0-100). Падает на −1 каждые 30с. Если слишком низко, сотрудник может забастовать и заморозить свою станцию.", zh: "幸福指数（0-100）。每30秒降1点。过低时员工可能罢工并冻结其工位。"},
  'staff.help_stress':    { fr: 'Monte à chaque BOOST utilisé. Si ça atteint 100%, l\'employé fait un burn-out et son poste se verrouille jusqu\'à ce que le stress redescende à 0.', en: 'Rises with each BOOST used. At 100%, the employee burns out and their station locks until stress returns to 0.', es: 'Sube con cada BOOST usado. Al 100%, el empleado sufre burn-out y su puesto se bloquea hasta que el estrés vuelve a 0.', de: "Steigt mit jedem BOOST. Bei 100% Burnout: Posten gesperrt, bis Stress wieder auf 0 ist." , it: "Aumenta a ogni BOOST usato. Al 100%, il dipendente va in burnout e la sua postazione si blocca finché lo stress non torna a 0.", ru: "Растёт с каждым использованным БУСТОМ. На 100% сотрудник выгорает и его станция блокируется, пока стресс не вернётся к 0.", zh: "每次使用加速时上升。100%时员工倦怠，工位锁定直至压力回到0。"},
  'staff.help_salary_lbl':{ fr: 'Salaire', en: 'Salary', es: 'Sueldo', de: "Gehalt" , it: "Stipendio", ru: "Зарплата", zh: "工资"},
  'staff.help_salary':    { fr: 'Trois niveaux : bas (perf ×0.8), standard (×1), haut (×1.2). Plus le salaire est haut, plus l\'employé est productif et moins il craque.', en: 'Three levels: low (perf ×0.8), standard (×1), high (×1.2). Higher salary = more productive, less likely to crack.', es: 'Tres niveles: bajo (rend. ×0.8), estándar (×1), alto (×1.2). Más sueldo = más productivo y menos propenso a romperse.', de: "Drei Stufen: niedrig (Leist ×0.8), Standard (×1), hoch (×1.2). Höheres Gehalt = produktiver, stabiler." , it: "Tre livelli: basso (perf ×0.8), standard (×1), alto (×1.2). Stipendio più alto = più produttivo, meno a rischio di crollo.", ru: "Три уровня: низкая (эфф ×0.8), стандарт (×1), высокая (×1.2). Выше зарплата = продуктивнее, меньше шанс сорваться.", zh: "三档：低（绩效×0.8）、标准（×1）、高（×1.2）。工资越高=越高效，越不易崩溃。"},
  'staff.help_bonus':     { fr: 'Bouton à dispo une fois par saison (120s). Coûte 2× le salaire et donne +20 moral. À utiliser quand le moral descend en zone rouge.', en: 'Available once per season (120s). Costs 2× salary and gives +20 moral. Use when moral drops into the red.', es: 'Disponible una vez por estación (120s). Cuesta 2× el sueldo y da +20 moral. Úsala cuando el moral entra en rojo.', de: "Einmal pro Saison (120s). Kostet 2× Gehalt, gibt +20 Moral. Nutze es, wenn die Moral in den roten Bereich fällt." , it: "Disponibile una volta a stagione (120s). Costa 2× lo stipendio e dà +20 morale. Usalo quando il morale va in rosso.", ru: "Доступен раз за сезон (120с). Стоит 2× зарплаты и даёт +20 морали. Используйте, когда мораль падает в красную зону.", zh: "每季可用一次（120秒）。花费2倍工资，给+20士气。士气进入红区时使用。"},
